//! The allow-default posture (`AllowDefaultPolicy`): the world starts
//! open — `(allow default)` — and the policy's denies narrow it. The
//! complement of the crate's deny-by-default `Policy`: there, what is
//! not granted does not exist; here, only what is denied is withheld.
//! The natural shape for confining an agent-style guest that must read
//! the workspace: writes denied everywhere but the grant, reads and
//! network open unless the policy narrows them.
//!
//! The profile is generated by the free function
//! [`allow_default_profile`] — no methods on the struct — so the policy
//! stays a plain data record and the generator stays pure and
//! inspectable.
//!
//! Enforcement gaps, named: Seatbelt matches a rule against the path an
//! access resolves to, so this posture cannot give a command an empty
//! directory of its own (no tmpfs) or mount an overlay (no mount
//! namespace). Deny-by-default `Policy` via Landlock covers those on
//! Linux; this posture is macOS-first by construction.
//!
//! Profile-generation ideas credited to the MIT-licensed `sandbox-jail`
//! crate (rename-escape parent pinning, deny-after-allow ordering, the
//! `/dev` carve-outs).

use crate::error::Error;
use std::fmt::Write as _;
use std::path::{Path, PathBuf};

/// Everything, or only the listed items.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[cfg_attr(feature = "serde", serde(rename_all = "snake_case"))]
pub enum Access<T> {
    #[default]
    All,
    Only(Vec<T>),
}

/// What the command may NOT touch; the rest of the world stays open.
/// Every path must be absolute — a relative path in a deny list would
/// silently rule nothing.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
#[cfg_attr(
    feature = "serde",
    derive(serde::Serialize, serde::Deserialize),
    serde(default, deny_unknown_fields)
)]
pub struct AllowDefaultPolicy {
    /// Directories the command may write. Everything else is denied.
    pub writable: Vec<PathBuf>,
    /// Directories it may not write, even inside `writable`.
    pub read_only: Vec<PathBuf>,
    /// Paths it may not replace or remove, while what is INSIDE a
    /// directory stays writable. Seatbelt only — Landlock has no such
    /// right.
    pub pinned: Vec<PathBuf>,
    /// Directories whose files it may not read, except `readable` and
    /// `writable` paths inside them.
    pub unreadable: Vec<PathBuf>,
    /// Exceptions inside `unreadable`.
    pub readable: Vec<PathBuf>,
    /// Paths it may not read or list, even inside `readable` or
    /// `writable`.
    pub hidden: Vec<PathBuf>,
    /// TCP and UDP.
    pub network: bool,
    /// Unix sockets it may connect to, by the directory they are in.
    /// The DNS resolver's socket is always allowed — name resolution
    /// dies without it.
    pub unix_sockets: Access<PathBuf>,
    /// Binaries it may not run. Seatbelt has no `NO_NEW_PRIVS`: a
    /// setuid binary it runs executes AS ROOT, and no other rule undoes
    /// that — the only defense is to never run it. Fill this with
    /// [`crate::known::setuid_binaries`] (see
    /// [`AllowDefaultPolicy::hardened`]).
    pub no_exec: Vec<PathBuf>,
}

impl AllowDefaultPolicy {
    /// The posture a confining caller usually wants: writes confined to
    /// `root`, the world readable, network open.
    #[must_use]
    pub fn write_confined(root: impl Into<PathBuf>) -> Self {
        Self {
            writable: vec![root.into()],
            ..Self::default()
        }
    }

    /// `write_confined` PLUS the setuid defense: every setuid binary on
    /// the system and `launchctl` — which talks to launchd over the
    /// bootstrap port no rule covers — are denied exec. Everything else
    /// stays open. The setuid scan is a SNAPSHOT at first call: binaries
    /// installed later are not covered, so build the policy fresh (or
    /// re-scan) for a long-lived confinement.
    #[must_use]
    pub fn hardened(root: impl Into<PathBuf>) -> Self {
        let mut policy = Self::write_confined(root);
        policy.no_exec = crate::known::setuid_binaries().to_vec();
        policy.no_exec.push(PathBuf::from(crate::known::LAUNCHCTL));
        policy
    }

    /// Replace the `no_exec` list.
    #[must_use]
    pub fn with_no_exec(mut self, binaries: Vec<PathBuf>) -> Self {
        self.no_exec = binaries;
        self
    }
}

/// The real path, or for a missing one its real parent and its name, or
/// the path as given. Seatbelt matches the path an access RESOLVES to,
/// so `/tmp` must become `/private/tmp` before it means anything to a
/// rule.
#[must_use]
pub fn real(path: &Path) -> PathBuf {
    if let Ok(p) = path.canonicalize() {
        return p;
    }

    match (path.parent().map(Path::canonicalize), path.file_name()) {
        (Some(Ok(parent)), Some(name)) => parent.join(name),
        _ => path.to_path_buf(),
    }
}

/// The policy with every path resolved, as the sandbox will match it,
/// with symlink aliases deduplicated (one dir listed as both `/var/run`
/// and `/run` would rule twice).
#[must_use]
pub fn resolved(mut policy: AllowDefaultPolicy) -> AllowDefaultPolicy {
    let lists = [
        &mut policy.writable,
        &mut policy.read_only,
        &mut policy.pinned,
        &mut policy.unreadable,
        &mut policy.readable,
        &mut policy.hidden,
        &mut policy.no_exec,
    ];

    for list in lists {
        for path in list.iter_mut() {
            *path = real(path);
        }

        let mut seen = std::collections::HashSet::new();
        list.retain(|p| seen.insert(p.clone()));
    }

    if let Access::Only(dirs) = &mut policy.unix_sockets {
        for dir in dirs.iter_mut() {
            *dir = real(dir);
        }

        let mut seen = std::collections::HashSet::new();
        dirs.retain(|d| seen.insert(d.clone()));
    }

    policy
}

/// The quoted SBPL string for `path`.
///
/// # Errors
/// `Error::Policy` for a path that is not UTF-8: lossy conversion would
/// name a path that never matches, silently ruling nothing.
fn quote(p: &Path) -> Result<String, Error> {
    let s = p.to_str().ok_or_else(|| {
        Error::Policy(format!(
            "{}: not UTF-8 — a lossy path would rule nothing",
            p.display()
        ))
    })?;
    Ok(format!(
        "\"{}\"",
        s.replace('\\', "\\\\").replace('"', "\\\"")
    ))
}

fn filters(kind: &str, paths: &[PathBuf]) -> Result<String, Error> {
    paths
        .iter()
        .map(|p| quote(p).map(|q| format!(" ({kind} {q})")))
        .collect()
}

/// Every parent of a read-only, pinned or hidden path that the command
/// could RENAME. Seatbelt matches the path at each access, so renaming
/// a parent moves the ruled path out from under its rule — a process
/// with write access to `/home` could rename `/home/.config` and write
/// where `.config/git` used to be. Denying writes to each parent itself
/// keeps it in place, while what is inside it stays writable.
#[must_use]
pub fn ruled_parents(p: &AllowDefaultPolicy) -> Vec<PathBuf> {
    let mut parents: Vec<PathBuf> = p
        .read_only
        .iter()
        .chain(&p.pinned)
        .chain(&p.hidden)
        .flat_map(|path| path.ancestors().skip(1))
        .filter(|a| p.writable.iter().any(|w| a.starts_with(w)))
        .map(Path::to_path_buf)
        .collect();
    parents.sort();
    parents.dedup();
    parents
}

/// The `sandbox-exec`-shaped profile for `policy`: `(allow default)`,
/// then each deny after the allow it narrows — the last rule that
/// matches wins. An allow with no filter allows everything, so an empty
/// list never writes one.
///
/// # Errors
/// `Error::Policy` when a path is not absolute: a relative path in a
/// deny list would silently rule nothing.
pub fn allow_default_profile(policy: &AllowDefaultPolicy) -> Result<String, Error> {
    if let Some(p) = policy
        .writable
        .iter()
        .chain(&policy.read_only)
        .chain(&policy.pinned)
        .chain(&policy.unreadable)
        .chain(&policy.readable)
        .chain(&policy.hidden)
        .chain(&policy.no_exec)
        .find(|p| !p.is_absolute())
    {
        return Err(Error::Policy(format!(
            "{}: not an absolute path — a relative path in a deny list would rule nothing",
            p.display()
        )));
    }

    let p = &resolved(policy.clone());
    let mut out = String::from("(version 1)\n(allow default)\n(deny file-write*)\n");
    let writable = filters("subpath", &p.writable)?;
    let _ = writeln!(
        out,
        "(allow file-write*{writable} (literal \"/dev/null\") (regex #\"^/dev/fd/\"))"
    );

    let mut pinned = p.pinned.clone();
    pinned.extend(ruled_parents(p));

    if !pinned.is_empty() {
        let _ = writeln!(out, "(deny file-write*{})", filters("literal", &pinned)?);
    }

    // A hidden path that could be renamed would leave its rule behind
    let fixed: Vec<PathBuf> = p.read_only.iter().chain(&p.hidden).cloned().collect();

    if !fixed.is_empty() {
        let _ = writeln!(out, "(deny file-write*{})", filters("subpath", &fixed)?);
    }

    if !p.unreadable.is_empty() {
        let _ = writeln!(
            out,
            "(deny file-read-data{})",
            filters("subpath", &p.unreadable)?
        );
        let allowed = filters("subpath", &p.readable)? + &writable;

        if !allowed.is_empty() {
            let _ = writeln!(out, "(allow file-read-data{allowed})");
        }
    }

    if !p.hidden.is_empty() {
        let _ = writeln!(out, "(deny file-read*{})", filters("subpath", &p.hidden)?);
    }

    // A literal filter: the binary is denied at exactly this path, so a
    // copy of it in a writable dir stays runnable — copies of setuid
    // binaries are not setuid, which is the point of a literal
    if !p.no_exec.is_empty() {
        let _ = writeln!(
            out,
            "(deny process-exec*{})",
            filters("literal", &p.no_exec)?
        );
    }

    if !p.network {
        out += "(deny network-outbound (remote ip))\n(deny network-bind (local ip))\n";
    }

    if let Access::Only(dirs) = &p.unix_sockets {
        out += "(deny network-outbound (remote unix-socket))\n";
        // Name resolution goes through this one socket; without the
        // carve-out a socket allow-list silently breaks every lookup
        out += "(allow network-outbound (remote unix-socket (path-literal \"/private/var/run/mDNSResponder\")))\n";
        // A `remote unix-socket` filter takes ONE path, so each dir
        // gets its own rule — no list form exists
        let sockets: String = dirs
            .iter()
            .map(|d| {
                quote(d).map(|q| {
                    format!(" (allow network-outbound (remote unix-socket (subpath {q})))")
                })
            })
            .collect::<Result<_, _>>()?;

        if !sockets.is_empty() {
            out += &sockets;
            out += "\n";
        }
    }

    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    #[allow(clippy::unwrap_used)]
    fn empty_lists_write_no_allow_that_matches_everything() {
        let policy = AllowDefaultPolicy {
            unreadable: vec!["/u".into()],
            unix_sockets: Access::Only(vec![]),
            ..AllowDefaultPolicy::default()
        };
        let profile = allow_default_profile(&policy).unwrap();

        for rule in ["file-read-data", "network-outbound"] {
            assert!(
                !profile.contains(&format!("(allow {rule})")),
                "a bare allow rules everything: {profile}"
            );
        }
    }

    #[test]
    #[allow(clippy::unwrap_used)]
    fn each_deny_comes_after_the_allow_it_narrows() {
        // the last matching rule wins, so order IS semantics
        let policy = AllowDefaultPolicy {
            writable: vec!["/w".into()],
            read_only: vec!["/w/ro".into()],
            hidden: vec!["/w/secret".into()],
            unreadable: vec!["/w".into()],
            ..AllowDefaultPolicy::default()
        };
        let profile = allow_default_profile(&policy).unwrap();
        let at = |s: &str| {
            profile
                .find(s)
                .unwrap_or_else(|| unreachable!("{s} missing from {profile}"))
        };
        assert!(
            at("(allow file-write* (subpath \"/w\")") < at("(deny file-write* (subpath \"/w/ro\")")
        );
        // the unreadable deny comes first, the exception allow narrows
        // it back, and the hidden deny lands after BOTH — it wins over
        // everything, as it must
        assert!(
            at("(deny file-read-data (subpath \"/w\")")
                < at("(allow file-read-data (subpath \"/w\")")
        );
        assert!(
            at("(allow file-read-data (subpath \"/w\")")
                < at("(deny file-read* (subpath \"/w/secret\")")
        );
    }

    #[test]
    #[allow(clippy::unwrap_used)]
    fn pins_each_parent_of_a_ruled_path_inside_a_writable_dir() {
        // real dirs: generation resolves every path, and macOS firmlinks
        // would rewrite /home — the pins must match what it resolved to
        let dir = tempfile::tempdir().unwrap();
        let home = real(dir.path());
        let policy = AllowDefaultPolicy {
            writable: vec![home.clone()],
            read_only: vec![home.join(".config/git")],
            hidden: vec![PathBuf::from("/elsewhere/key")],
            ..AllowDefaultPolicy::default()
        };
        // /elsewhere is outside every writable dir — nothing to pin
        assert_eq!(
            ruled_parents(&policy),
            vec![home.clone(), home.join(".config")]
        );
        let profile = allow_default_profile(&policy).unwrap();
        assert!(
            profile.contains(&format!(
                "(deny file-write* (literal \"{}\") (literal \"{}\"))",
                home.display(),
                home.join(".config").display()
            )),
            "{profile}"
        );
    }

    #[test]
    #[allow(clippy::unwrap_used)]
    fn quotes_a_path_with_a_quote() {
        let policy = AllowDefaultPolicy {
            writable: vec!["/a\"b".into()],
            ..AllowDefaultPolicy::default()
        };
        assert!(
            allow_default_profile(&policy)
                .unwrap()
                .contains("(subpath \"/a\\\"b\")")
        );
    }

    #[test]
    fn refuses_a_relative_path() {
        let policy = AllowDefaultPolicy {
            hidden: vec!["relative".into()],
            ..AllowDefaultPolicy::default()
        };
        let Err(err) = allow_default_profile(&policy) else {
            unreachable!("a relative path must be refused");
        };
        assert!(
            matches!(err, Error::Policy(m) if m.contains("relative") && m.contains("absolute"))
        );
    }

    /// A lossy path would rule a path that never matches — the deny
    /// silently protects nothing. Refused, loudly.
    #[test]
    fn refuses_a_non_utf8_path() {
        use std::ffi::OsStr;
        use std::os::unix::ffi::OsStrExt;
        let policy = AllowDefaultPolicy {
            hidden: vec![PathBuf::from(OsStr::from_bytes(b"/tmp/\xff\xfebad"))],
            ..AllowDefaultPolicy::default()
        };
        let Err(err) = allow_default_profile(&policy) else {
            unreachable!("a non-UTF-8 path must be refused");
        };
        assert!(
            matches!(err, Error::Policy(ref m) if m.contains("UTF-8")),
            "{err}"
        );
    }

    #[test]
    #[allow(clippy::unwrap_used)]
    fn a_dir_listed_twice_through_a_symlink_appears_once() {
        let dir = tempfile::tempdir().unwrap();
        let run = dir.path().join("run");
        std::fs::create_dir(&run).unwrap();
        std::os::unix::fs::symlink(&run, dir.path().join("var-run")).unwrap();
        let policy = AllowDefaultPolicy {
            writable: vec![run.clone(), dir.path().join("var-run")],
            ..AllowDefaultPolicy::default()
        };
        let profile = allow_default_profile(&policy).unwrap();
        assert_eq!(
            profile
                .matches(&format!("(subpath \"{}\")", real(&run).display()))
                .count(),
            1,
            "{profile}"
        );
    }

    #[test]
    #[allow(clippy::unwrap_used)]
    fn resolves_a_missing_path_through_its_parent() {
        let dir = tempfile::tempdir().unwrap();
        let missing = dir.path().join("missing");
        assert_eq!(
            real(&missing),
            dir.path().canonicalize().unwrap().join("missing")
        );
    }

    #[test]
    #[allow(clippy::unwrap_used)]
    fn unix_socket_allows_come_one_per_dir_with_the_dns_carve_out() {
        let policy = AllowDefaultPolicy {
            unix_sockets: Access::Only(vec!["/run/agent".into()]),
            ..AllowDefaultPolicy::default()
        };
        let profile = allow_default_profile(&policy).unwrap();
        assert!(profile.contains("(deny network-outbound (remote unix-socket))"));
        assert!(profile.contains("mDNSResponder"));
        assert!(
            profile
                .contains("(allow network-outbound (remote unix-socket (subpath \"/run/agent\")))")
        );
    }

    #[test]
    #[allow(clippy::unwrap_used)]
    fn a_socket_dir_listed_twice_through_a_symlink_appears_once() {
        let dir = tempfile::tempdir().unwrap();
        let run = dir.path().join("run");
        std::fs::create_dir(&run).unwrap();
        std::os::unix::fs::symlink(&run, dir.path().join("var-run")).unwrap();
        let policy = AllowDefaultPolicy {
            unix_sockets: Access::Only(vec![run.clone(), dir.path().join("var-run")]),
            ..AllowDefaultPolicy::default()
        };
        let profile = allow_default_profile(&policy).unwrap();
        assert_eq!(
            profile
                .matches(&format!(
                    "(remote unix-socket (subpath \"{}\"))",
                    real(&run).display()
                ))
                .count(),
            1,
            "{profile}"
        );
    }

    #[test]
    #[allow(clippy::unwrap_used)]
    fn no_exec_denies_each_binary_at_its_literal_path() {
        let policy = AllowDefaultPolicy {
            no_exec: vec!["/usr/bin/sudo".into()],
            ..AllowDefaultPolicy::default()
        };
        let profile = allow_default_profile(&policy).unwrap();
        assert!(
            profile.contains("(deny process-exec* (literal \"/usr/bin/sudo\"))"),
            "{profile}"
        );
        // and the deny lands after (allow default) — last match wins
        assert!(
            profile.find("(allow default)").unwrap() < profile.find("(deny process-exec*").unwrap()
        );
    }

    /// The setuid defense, as a caller gets it: the hardened preset
    /// names the real setuid binaries this system ships plus launchctl.
    #[test]
    #[allow(clippy::unwrap_used)]
    #[cfg(target_os = "macos")]
    fn hardened_denies_the_setuid_binaries_and_launchctl() {
        let policy = AllowDefaultPolicy::hardened("/tmp/jail");
        assert!(
            policy.no_exec.iter().any(|p| p.ends_with("sudo")),
            "{:?}",
            policy.no_exec
        );
        assert!(
            policy
                .no_exec
                .iter()
                .any(|p| p == Path::new(crate::known::LAUNCHCTL))
        );
        let profile = allow_default_profile(&policy).unwrap();
        let Some(deny) = profile
            .split('\n')
            .find(|l| l.starts_with("(deny process-exec*"))
        else {
            unreachable!("no deny rule in {profile}");
        };
        for binary in &policy.no_exec {
            assert!(
                deny.contains(&format!("(literal \"{}\")", binary.display())),
                "{binary:?} missing from {deny}"
            );
        }
    }
}
